import type { ImageStorageProvider } from '@nsb/shared';

export interface StoreInput {
  buffer: Buffer;
  ext: string;
  mimeType: string;
  /** Sub-folder such as "banners"; file names are always generated by the server. */
  folder: string;
}

export interface StoredImage {
  /** Public URL saved on records: absolute for cloud providers, /api/uploads/... for local files. */
  url: string;
  /** Provider-specific id used to delete the file later. */
  key: string;
  /** Cloudinary cloud name or Firebase bucket that holds the file; null for local files. */
  account: string | null;
}

/**
 * One place images can be kept. MediaService picks the provider; business logic never does.
 * Credentials are read on each call, so changes saved in Settings apply immediately.
 */
export interface ImageStorage {
  readonly provider: ImageStorageProvider;
  isConfigured(): Promise<boolean>;
  store(input: StoreInput): Promise<StoredImage>;
  /**
   * Deletes the file; succeeds if it is already gone. Throws when the provider is now set up
   * for a different account than `account`, so files are never deleted with the wrong keys.
   */
  remove(key: string, account: string | null): Promise<void>;
}

export class AccountChangedError extends Error {
  constructor(provider: string, stored: string | null, current: string | null) {
    super(`${provider} file is in "${stored}" but the current credentials are for "${current ?? 'none'}"`);
  }
}
